sys.path.append(os.getcwd())
import numpy as np, bpy
from tool import load, cls, NAMES

def rle(seq):
    res = []; s = seq[0]; st = 0
    for i in range(1, len(seq)+1):
        if i == len(seq) or seq[i] != s:
            res.append([s, st, i-1]); s = seq[i] if i < len(seq) else None; st = i
    return res

def prof(img, axis, idx, minlen=2):
    a = load(img)
    line = a[idx, :] if axis == 'row' else a[:, idx]
    c = cls(np.stack([line, line, line], -1))
    rs = [x for x in rle(c) if (x[2]-x[1] >= minlen-1)]
    print("  %s %s=%d: %s" % (img.split('/')[-1], axis, idx,
        "  ".join("%s[%d-%d]" % (NAMES[x[0]], x[1], x[2]) for x in rs)))

F='inputs/view_front.png'
for py in [100,110,130,160,180,200,210,230,700,1140,1150,1160,1175,1190,1200,1210,1215]:
    prof(F,'row',py)
for px in [100,120,140,145,200,215,240,250,300,345,380,390,420,430,455,470,480,500,510,530,560,590,600,610,620,640,660,680,690]:
    prof(F,'col',px)
", "path": "s2.py"}

